import pdfplumber
import openpyxl
import json
import re

def parse_numeric(value):
    """Parse numeric values from strings"""
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return value
    if isinstance(value, str):
        # Remove commas and convert to number
        try:
            cleaned = value.replace(',', '')
            if '.' in cleaned:
                return float(cleaned)
            else:
                return int(cleaned)
        except:
            return value
    return value

# Extract data from PDF
pdf_data = {}
with pdfplumber.open('/root/employees_backup.pdf') as pdf:
    for page in pdf.pages:
        table = page.extract_table()
        if table:
            headers = table[0]
            for row in table[1:]:
                if row[0] and str(row[0]).startswith('EMP'):
                    emp_id = str(row[0]).strip()
                    pdf_data[emp_id] = {}
                    for i, header in enumerate(headers):
                        if i < len(row):
                            value = row[i]
                            if value is not None:
                                # Parse numeric fields
                                if header in ['Salary', 'Years', 'Score']:
                                    pdf_data[emp_id][header] = parse_numeric(value)
                                else:
                                    pdf_data[emp_id][header] = value
                            else:
                                pdf_data[emp_id][header] = None

# Extract data from Excel
excel_data = {}
wb = openpyxl.load_workbook('/root/employees_current.xlsx')
ws = wb.active

headers = None
for row in ws.iter_rows(min_row=1, values_only=True):
    if headers is None:
        headers = row
    else:
        if row[0] and str(row[0]).startswith('EMP'):
            emp_id = str(row[0]).strip()
            excel_data[emp_id] = {}
            for i, header in enumerate(headers):
                if i < len(row):
                    value = row[i]
                    excel_data[emp_id][header] = value
                else:
                    excel_data[emp_id][header] = None

# Identify deleted employees (in PDF but not in Excel)
deleted_employees = sorted([emp_id for emp_id in pdf_data.keys() if emp_id not in excel_data])

# Identify modified employees
modified_employees = []
for emp_id in sorted(excel_data.keys()):
    if emp_id in pdf_data:
        pdf_record = pdf_data[emp_id]
        excel_record = excel_data[emp_id]

        # Check each field for changes
        for field in headers:
            if field == 'ID':
                continue

            pdf_value = pdf_record.get(field)
            excel_value = excel_record.get(field)

            # Normalize for comparison
            if field in ['Salary', 'Years', 'Score']:
                pdf_normalized = parse_numeric(pdf_value)
                excel_normalized = excel_value
            else:
                pdf_normalized = str(pdf_value).strip() if pdf_value else None
                excel_normalized = str(excel_value).strip() if excel_value else None

            # Compare
            if pdf_normalized != excel_normalized:
                modified_employees.append({
                    "id": emp_id,
                    "field": field,
                    "old_value": pdf_normalized,
                    "new_value": excel_normalized
                })

# Sort modified employees by ID
modified_employees.sort(key=lambda x: x['id'])

# Create report
report = {
    "deleted_employees": deleted_employees,
    "modified_employees": modified_employees
}

# Write to JSON file
with open('/root/diff_report.json', 'w') as f:
    json.dump(report, f, indent=2)

print(f"Report generated successfully!")
print(f"Deleted employees: {len(deleted_employees)}")
print(f"Modified employees: {len(modified_employees)}")
print(f"\nFirst 5 deleted employees: {deleted_employees[:5]}")
print(f"\nFirst 5 modified employees:")
for mod in modified_employees[:5]:
    print(f"  {mod}")

EOF

